"354 :     public Object getValue(String xpath, Expression expr) {
355 :         Object result = expr.computeValue(getEvalContext());
356 :         if (result == null) {
357 :             if (expr instanceof Path && !isLenient()) {
358 :                 throw new JXPathNotFoundException("No value for xpath: "
359 :                         + xpath);
360 :             }
361 :             return null;
362 :         }
363 :         if (result instanceof EvalContext) {
364 :             EvalContext ctx = (EvalContext) result;
365 :             result = ctx.getSingleNodePointer();
366 :             if (!isLenient() && result == null) {
367 :                 throw new JXPathNotFoundException("No value for xpath: "
368 :                         + xpath);
369 :             }
370 :         }
371 :         if (result instanceof NodePointer) {
372 :             result = ((NodePointer) result).getValuePointer();
373 :             if (!isLenient() && !((NodePointer) result).isActual()) {
374 :                 // We need to differentiate between pointers representing
375 :                 // a non-existing property and ones representing a property
376 :                 // whose value is null.  In the latter case, the pointer
377 :                 // is going to have isActual == false, but its parent,
378 :                 // which is a non-node pointer identifying the bean property,
379 :                 // will return isActual() == true.
380 :                 NodePointer parent =
381 :                     ((NodePointer) result).getImmediateParentPointer();
382 :                 if (parent == null
383 :                     || !parent.isContainer()
384 :                     || !parent.isActual()) {
385 :                     throw new JXPathNotFoundException("No value for xpath: "
386 :                             + xpath);
387 :                 }
388 :             }
389 :             result = ((NodePointer) result).getValue();
390 :         }
391 :         return result;
392 :     }"

